    test(
      '/approval autopilot: renamed unattended mode, legacy alias kept',
      () async {
        final cli = cliFor([], approvalMode: ApprovalMode.yolo);
        final run = cli.run();
        io.sendLine('/approval');
        await _waitFor(
          () => io.out.toString().contains(
            'approval modes: always-ask, write, yolo, autopilot',
          ),
        );
        io.sendLine('/approval autopilot');
        await _waitFor(
          () => io.out.toString().contains('approval mode set to autopilot'),
        );
        expect(cli.approval.mode, ApprovalMode.unattended);
        // The pre-rename spelling keeps working (persisted configs, muscle
        // memory): same mode, labeled autopilot.
        io.sendLine('/approval write');
        await _waitFor(
          () => io.out.toString().contains('approval mode set to write'),
        );
        expect(cli.approval.mode, ApprovalMode.write);
        io.sendLine('/approval unattended');
        await _waitFor(() => cli.approval.mode == ApprovalMode.unattended);
        // The unknown-mode hint names the new spelling.
        io.sendLine('/approval bogus');
        await _waitFor(
          () => io.out.toString().contains(
            '(want always-ask|write|yolo|autopilot)',
          ),
        );
        expect(cli.approval.mode, ApprovalMode.unattended);
        io.sendLine('/exit');
        await run;
      },
    );

    test('/allow adds a known tool and lists the set', () async {
      var changes = 0;
      final cli = cliFor([], onApprovalChanged: () => changes++);
      final run = cli.run();
      io.sendLine('/allow bash');
      await _waitFor(() => io.out.toString().contains('"bash" always allowed'));
      expect(cli.approval.alwaysAllowedTools, ['bash']);
      expect(changes, 1);
      io.sendLine('/allow nosuchtool');
      await _waitFor(
        () => io.out.toString().contains('unknown tool: nosuchtool'),
      );
      expect(changes, 1);
      io.sendLine('/allow');
      await _waitFor(
        () => io.out.toString().contains('always-allowed tools: bash'),
      );
      io.sendLine('/exit');
      await run;
    });

    test('config alwaysAllowTools seeds the manager', () {
      final cli = cliFor([], alwaysAllowTools: const {'bash', 'write'});
      expect(cli.approval.alwaysAllowedTools, ['bash', 'write']);
    });

    test('/help mentions the approval commands', () async {
      final cli = cliFor([]);
      final run = cli.run();
      io.sendLine('/help');
      await _waitFor(() => io.out.toString().contains('/approval'));
      expect(io.out.toString(), contains('/allow'));
      io.sendLine('/exit');
      await run;
    });
  });

  // gh-1204: the Terminal visual leg went red asserting the bare `/approval`
  // picker marks the active mode with `(current)`. These cheap dart-test
  // pins cover the picker-item contract without a PTY so a regression here
  // fails the fast core lane pre-merge.
  group('TUI approval picker items', () {
    test('always-ask mode is the single (current) row', () {
      final cli = cliFor([], approvalMode: ApprovalMode.alwaysAsk);
      final items = cli.approvalPickerItemsForTest();
      expect(items.map((i) => i.label), [
        'always-ask',
        'write',
        'yolo',
        'autopilot',
      ]);
      final marked = items
          .where((i) => i.description.contains('(current)'))
          .toList(growable: false);
      expect(marked, hasLength(1), reason: 'exactly one row is current');
      expect(marked.single.label, 'always-ask');
      expect(
        marked.single.description,
        contains('prompt before every write/exec tool call'),
        reason: 'the marker rides the row description, not a separate row',
      );
    });

    test('/approval <mode> moves the (current) marker', () async {
      final cli = cliFor([], approvalMode: ApprovalMode.write);
      final run = cli.run();
      io.sendLine('/approval yolo');
      await _waitFor(
        () => io.out.toString().contains('approval mode set to yolo'),
      );
      final marked = cli
          .approvalPickerItemsForTest()
          .where((i) => i.description.contains('(current)'))
          .toList(growable: false);
      expect(marked, hasLength(1), reason: 'exactly one row is current');
      expect(marked.single.label, 'yolo');
      io.sendLine('/exit');
      await run;
    });
  });
